/**
 * Rules digest and lookup · TODO 288.
 *
 * A new feature used to mean reading CLAUDE.md and several `.claude/rules/*.md` files whole
 * (~50k tokens for all of them). The digest is ONE generated file listing every rules section
 * as one line: its heading, the book pages it cites (with the PDF to open), and the modules and
 * tests it names. The lookup prints just the sections that match a topic.
 *
 *   node tools/rules-digest.mjs --write        regenerate .claude/rules-digest.md
 *   node tools/rules-digest.mjs --check        exit 1 if the digest is stale (changes nothing)
 *   node tools/rules-digest.mjs <topic...>     print matching sections + PDF pointers
 *
 * ⚠ It never copies rulebook text: it reads only this repo's own rules files and points at
 * printed pages. It never reads SR-OCR/.
 */
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const RULES_DIR = join(ROOT, '.claude', 'rules');
export const DIGEST = join(ROOT, '.claude', 'rules-digest.md');
export const PDF_DIR = 'C:\\Users\\lance\\Documents\\Github\\Shadowrun 3rd Edition PDFs';

/** Book code → PDF file and printed→PDF page offset (null = not verified; open by printed page). */
export const BOOKS = {
  SR3:  { pdf: 'Shadowrun 3e - Core Rules {FAN25000}.pdf', offset: 2 },
  MDF:  { pdf: 'Shadowrun 3e - The Matrix Defragged v2.pdf', offset: null },
  CC:   { pdf: 'Shadowrun 3e - Cannon Companion.pdf', offset: null },
  MITS: { pdf: 'Shadowrun 3e - Magic in the Shadows.pdf', offset: null },
  R3:   { pdf: 'Shadowrun 3e - Rigger 3 Revised {FanPro10662}.pdf', offset: null },
  MM:   { pdf: 'Shadowrun 3e - Man and Machine Cyberware {FASA7126}.pdf', offset: null },
};
const CODE_RE = /\b(SR3|MDF|CC|MitS|MITS|R3|SOTA2|M&M|MM)\s+p{1,2}\.\s?(\d+)(?:\s?[-–]\s?(\d+))?/g;
const norm = code => ({ MitS: 'MITS', 'M&M': 'MM' }[code] ?? code);

const read = p => readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
export const rulesFiles = () => readdirSync(RULES_DIR).filter(f => f.endsWith('.md')).sort();

/** Split one rules file into sections at `##`/`###`/`####` headings (front matter dropped). */
export function sections(text) {
  const body = text.replace(/^---\n[\s\S]*?\n---\n/, '');
  const out = [];
  let cur = null, fence = false;
  for (const line of body.split('\n')) {
    if (line.startsWith('```')) fence = !fence;
    const m = !fence && line.match(/^(#{1,4})\s+(.*)$/);
    if (m) { cur = { level: m[1].length, heading: m[2].trim(), lines: [line] }; out.push(cur); }
    else if (cur) cur.lines.push(line);
  }
  return out;
}

/** Every book citation in a piece of text, deduplicated in order. */
export function citations(text) {
  const seen = new Map();
  for (const m of text.matchAll(CODE_RE)) {
    const code = norm(m[1]), page = m[3] ? `${m[2]}-${m[3]}` : m[2];
    seen.set(`${code} p.${page}`, { code, page, first: Number(m[2]) });
  }
  // A page with no book code in front of it ("· *p.168-169*") — the book is unnamed in the source.
  for (const m of text.matchAll(/(?<![A-Za-z0-9&]\s?)(?<![A-Za-z0-9])pp?\.\s?(\d+)(?:\s?[-–]\s?(\d+))?/g)) {
    const page = m[2] ? `${m[1]}-${m[2]}` : m[1];
    if (![...seen.values()].some(c => c.page === page)) seen.set(`? p.${page}`, { code: '?', page, first: Number(m[1]) });
  }
  return [...seen.values()];
}

/** Where to open a citation: PDF name and PDF page when the offset is known. */
export function pdfFor({ code, first }) {
  const b = BOOKS[code];
  if (!b) return code === '?' ? 'book not named in the rules file — check the section' : `${code}: no PDF mapped`;
  return b.offset == null ? `${b.pdf} (printed p.${first}; offset unverified)` : `${b.pdf} PDF p.${first + b.offset}`;
}

/** Repo files a section names in backticks (modules, tests, tools). */
export function owners(text) {
  const set = new Set();
  for (const m of text.matchAll(/`([^`\s]+\.(?:m?js|json|css))(?::[^`]*)?`/g)) set.add(m[1]);
  return [...set];
}

const clean = h => h.replace(/\s*·?\s*\*[^*]*p\.[^*]*\*/g, '').replace(/[*`]/g, '').trim();
const hash = t => createHash('sha256').update(t).digest('hex').slice(0, 12);

export function buildDigest() {
  const files = rulesFiles();
  const out = [
    '<!-- GENERATED by `node tools/rules-digest.mjs --write` — do not edit. tests/rules-digest.test.mjs fails when stale. -->',
    '# Rules digest — one line per section of `.claude/rules/*.md`',
    '',
    'Read this instead of the rules files. Then `node tools/rules-digest.mjs <topic>` prints only the matching',
    'sections; open the cited PDF page for the rule itself (the PDFs are the authority).',
    `PDFs: \`${PDF_DIR}\`. SR3 core: PDF page = printed + 2.`,
    'Format: **heading** — citations — modules/tests named. Sources (sha256/12):',
    '',
  ];
  for (const f of files) out.push(`- \`${f}\` ${hash(read(join(RULES_DIR, f)))}`);
  for (const f of files) {
    const secs = sections(read(join(RULES_DIR, f)));
    out.push('', `## ${f.replace(/\.md$/, '')}`);
    for (const s of secs) {
      if (s.level === 1) continue;
      const text = s.lines.join('\n');
      const cites = citations(text).map(c => `${c.code} p.${c.page}`);
      const own = owners(text);
      out.push(`- **${clean(s.heading)}**${cites.length ? ` — ${cites.join(', ')}` : ' — *(no citation: not audited)*'}${own.length ? ` — ${own.join(', ')}` : ''}`);
    }
  }
  return out.join('\n') + '\n';
}

/** Sections across the rules files (and CLAUDE.md) whose heading or body matches every term. */
export function lookup(terms, { bodyToo = true } = {}) {
  const ts = terms.map(t => t.toLowerCase());
  const sources = [...rulesFiles().map(f => [`.claude/rules/${f}`, join(RULES_DIR, f)]), ['CLAUDE.md', join(ROOT, 'CLAUDE.md')]];
  const hits = [];
  for (const [rel, p] of sources) {
    for (const s of sections(read(p)).filter(x => x.level > 1)) {
      const head = s.heading.toLowerCase(), text = s.lines.join('\n');
      const hay = bodyToo ? text.toLowerCase() : head;
      if (ts.every(t => hay.includes(t))) hits.push({ rel, s, text, inHead: ts.every(t => head.includes(t)) });
    }
  }
  hits.sort((a, b) => b.inHead - a.inHead);
  return hits;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const args = process.argv.slice(2);
  if (args[0] === '--write') { writeFileSync(DIGEST, buildDigest()); console.log('wrote .claude/rules-digest.md'); }
  else if (args[0] === '--check') {
    const ok = existsSync(DIGEST) && read(DIGEST) === buildDigest();
    console.log(ok ? 'rules digest up to date' : 'rules digest STALE — run: node tools/rules-digest.mjs --write');
    process.exit(ok ? 0 : 1);
  } else if (!args.length) {
    console.log('usage: node tools/rules-digest.mjs <topic words> | --write | --check');
  } else {
    let hits = lookup(args);
    const headOnly = hits.filter(h => h.inHead);
    if (headOnly.length) hits = headOnly;
    if (!hits.length) { console.log(`no section mentions: ${args.join(' ')}`); process.exit(1); }
    for (const h of hits.slice(0, 6)) {
      console.log(`\n=== ${h.rel} — ${h.s.heading}`);
      for (const c of citations(h.text)) console.log(`    📖 ${c.code} p.${c.page} → ${pdfFor(c)}`);
      console.log(h.text.trim());
    }
    if (hits.length > 6) console.log(`\n… ${hits.length - 6} more: ${hits.slice(6).map(h => `${h.rel}: ${clean(h.s.heading)}`).join(' | ')}`);
  }
}
